const $=s=>document.querySelector(s);const navs=[['Dashboard','▦'],['Lộ trình học','◫'],['Thư viện bài học','▤'],['Flashcard','▱'],['Quiz','☑'],['Phỏng vấn','♧'],['Case study','◈'],['Glossary','Aa'],['Tin tức','▣']];
const tracks=[['Nền tảng Business Analysis','Vai trò, tư duy & kỹ năng cốt lõi',12,75,'#7771dc','◇'],['Khai thác yêu cầu','Hiểu đúng vấn đề, hỏi đúng câu hỏi',16,42,'#e7a05e','♧'],['Quản lý yêu cầu','Từ yêu cầu đến giá trị kinh doanh',14,28,'#5eaf95','▤'],['Mô hình hóa quy trình','Trực quan hóa với BPMN & Flowchart',18,60,'#668fd9','⌘'],['Phân tích & thiết kế giải pháp','Biến insight thành giải pháp khả thi',15,15,'#d381a4','◈'],['Dữ liệu & SQL cho BA','Đọc dữ liệu, đưa ra quyết định',20,10,'#739eaf','▥'],['Agile & Scrum','Làm việc hiệu quả cùng đội sản phẩm',12,0,'#b090d0','↻'],['UX & Product Thinking','Thiết kế trải nghiệm từ góc nhìn BA',14,0,'#d8aa55','✧'],['Testing & UAT','Đảm bảo giải pháp đáp ứng kỳ vọng',10,0,'#62aaa0','☑'],['Kỹ năng & Phỏng vấn BA','Tự tin sẵn sàng cho bước tiếp theo',16,0,'#8a91c5','♧']];
const lessonNames=['Business Analysis là gì?','Vai trò của BA trong dự án','Các nhóm stakeholder','Stakeholder Analysis & Mapping','Kỹ thuật phỏng vấn stakeholder','Xác định nhu cầu kinh doanh'];
let state;try{state=JSON.parse(localStorage.getItem('vy-workspace-state')||localStorage.getItem('ba-academy-state'))||{done:[],scores:{},dark:false,review:0}}catch{state={done:[],scores:{},dark:false,review:0}}let page='Dashboard',trackId=0,lessonId=3,tab=0,filter='all',flashIndex=0,quizIndex=0,answers=[],quizTrack=0;const save=()=>{localStorage.setItem('vy-workspace-state',JSON.stringify(state));localStorage.setItem('ba-academy-state',JSON.stringify(state));};const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const key=(t,l)=>t+'-'+l;const progress=t=>Math.min(100,tracks[t][3]+state.done.filter(x=>x.startsWith(t+'-')).length*4);const toast=m=>{$('#toast').textContent=m;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',3200)};
document.body.classList.toggle('dark',state.dark);
$('#sidebar').innerHTML=`<div class="brand"><em>◈</em><div>vy<span>workspace</span></div></div><div class="nav-label">KHÔNG GIAN HỌC TẬP</div><nav>${navs.map(([n,i])=>`<button class="nav-btn" data-nav="${n}" title="${n}"><span class="nav-icon">${i}</span><span class="nav-text">${n}</span></button>`).join('')}</nav><div class="side-end"><div class="side-promo"><b>Mỗi ngày, một bước tiến ✨</b><p>15 phút hôm nay.<br>Một phiên bản tốt hơn ngày mai.</p><button data-nav="Lộ trình học">Khám phá lộ trình</button></div><button class="nav-btn" data-nav="Cài đặt" title="Cài đặt"><span class="nav-icon">⚙</span><span class="nav-text">Cài đặt</span></button></div>`;
$('#bottom').innerHTML=navs.slice(0,5).map(([n,i])=>`<button data-nav="${n}"><span class="nav-icon">${i}</span>${n==='Thư viện bài học'?'Thư viện':n==='Lộ trình học'?'Lộ trình':n}</button>`).join('');
function go(n){page=n;$('#results').innerHTML='';$('#search').value='';render();window.scrollTo(0,0)}function openTrack(i){trackId=i;go('track')}function openLesson(t,l){trackId=t;lessonId=l;tab=0;go('lesson')}
function bar(v,c){return `<div class="progress" style="--progress:${v}%;--accent:${c||'#5b5bd6'}"><span></span></div>`}
function cards(){return tracks.map((t,i)=>({t,i})).filter(({i})=>filter==='all'||(filter==='learning'?progress(i)>0&&progress(i)<100:progress(i)===100)).map(({t,i})=>`<button class="track" style="--accent:${t[4]}" data-track="${i}"><div class="track-top"><span class="track-icon">${t[5]}</span><small>${i<4?'Cơ bản':i<8?'Trung cấp':'Nâng cao'}</small></div><h3>${t[0]}</h3><p>${t[2]} bài học · ${t[1]}</p><div class="progress-label"><span>${Math.floor(t[2]*progress(i)/100)}/${t[2]} bài học</span><b>${progress(i)}%</b></div>${bar(progress(i),t[4])}</button>`).join('')||'<div class="empty">Chưa có track hoàn thành. Tiếp tục cố gắng nhé!</div>'}
function heading(title,sub){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><span class="date">▦ &nbsp; Thứ Sáu, 20 tháng 11, 2026</span></div>`}
function trackSection(){return `<div class="section-head"><h2>Lộ trình của bạn <span class="subtle" style="font-size:11px;font-weight:400">&nbsp; 10 tracks</span></h2><div class="filters">${[['all','Tất cả'],['learning','Đang học'],['done','Hoàn thành']].map(([v,n])=>`<button data-filter="${v}" class="${filter===v?'selected':''}">${n}</button>`).join('')}</div></div><div class="tracks">${cards()}</div>`}
function dashboard(){return heading('Chào buổi chiều, Minh Anh 👋','Một chút học hỏi mỗi ngày, một bước gần hơn đến BA chuyên nghiệp.')+`<div class="dashboard-layout"><div><section class="hero"><div><div class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</div><h2>Nuôi dưỡng tư duy.<br>Kiến tạo giá trị.</h2><p>Hành trình Business Analyst của bạn bắt đầu từ hôm nay.</p><button class="primary" data-nav="Lộ trình học">Khám phá lộ trình</button></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><span class="spark">✦</span><div class="book">◈</div><div class="float-card">✦ &nbsp; Learn. Practice. Grow.</div></div></section><div class="stats">${[['▤',24+state.done.length,'Bài học đã hoàn thành','+4 bài trong tuần','#7771dc'],['☑',Object.keys(state.scores).length?Math.round(Object.values(state.scores).reduce((a,b)=>a+b,0)/Object.keys(state.scores).length)+'%':'82%','Điểm quiz trung bình','+8% so với tuần trước','#5eaf95'],['▱',Math.max(0,18-state.review),'Flashcard cần ôn hôm nay','Sẵn sàng ôn tập nào','#e7a05e'],['♨',7,'Ngày học liên tiếp','Bạn đang làm rất tốt!','#d381a4']].map(([icon,v,n,s,c])=>`<div class="stat"><span class="icon" style="background:${c}18;color:${c}">${icon}</span><strong>${v}</strong><p>${n}</p><small>${s}</small></div>`).join('')}</div>${trackSection()}<section class="panel chart"><div class="section-head"><h2>Bức tranh kỹ năng</h2><span class="metadata">Điểm đánh giá mẫu · /100</span></div>${[['Nền tảng BA',88],['Khai thác yêu cầu',76],['Mô hình hóa',65],['Dữ liệu & SQL',42],['Agile & Scrum',72]].map(([n,v])=>`<div class="bar-row"><span>${n}</span>${bar(v,v<50?'#e7a05e':'#8c87e7')}<b>${v}</b></div>`).join('')}<p class="metadata" style="margin-top:20px">✧ Dữ liệu & SQL là kỹ năng bạn có thể ưu tiên tiếp theo.</p></section></div><div class="right-col"><section class="panel"><span class="continue-tag">ĐANG HỌC</span><h2 class="continue-title">Stakeholder Analysis<br>& Mapping</h2><p class="metadata">Khai thác yêu cầu · Bài 04<br>◷ 12 phút đọc</p><div class="progress-label" style="margin-top:18px"><span>Tiến độ bài học</span><b>65%</b></div>${bar(65)}<button class="primary full" data-lesson="1,3">Tiếp tục học</button></section><section class="panel"><div class="section-head"><h2>Lịch học tập</h2><span>♨</span></div><div class="calendar-head"><span>Tháng 11, 2026</span><span>Tuần này</span></div><div class="calendar">${['T2','T3','T4','T5','T6','T7','CN'].map(d=>`<span>${d}</span>`).join('')}${Array.from({length:30},(_,i)=>`<span class="${i+1===20?'today':i+1>=14&&i+1<20?'done':''}">${i+1}</span>`).join('')}</div><div class="streak"><span style="font-size:24px">♨</span><div><b>7 ngày liên tiếp!</b><small>Giữ lửa học tập của bạn nhé.</small></div></div></section><section class="panel"><h3>Cần ôn hôm nay</h3>${[['▱','Thuật ngữ BA căn bản',Math.max(0,18-state.review)+' flashcard','Flashcard'],['☑','Requirement Elicitation','Quiz · 5 câu hỏi','Quiz']].map(([i,n,d,p])=>`<div class="review-row"><span class="review-icon">${i}</span><div><b>${n}</b><small>${d}</small></div><button data-nav="${p}" aria-label="Mở ${n}">▷</button></div>`).join('')}</section><section class="panel"><div class="section-head"><h2>Góc nhìn BA</h2><button data-nav="Tin tức">Xem tất cả</button></div><div class="news-item">Từ yêu cầu đến giá trị: tư duy outcome cho BA<small>Góc học tập · 5 phút đọc</small></div><div class="news-item">AI hỗ trợ BA như thế nào trong phân tích yêu cầu?<small>Chuyên đề · 8 phút đọc</small></div></section></div></div>`}
function trackPage(){let t=tracks[trackId];return `<button data-nav="Lộ trình học" class="subtle">Lộ trình học / ${t[0]}</button><div class="track-banner" style="margin-top:20px"><div class="eyebrow">LỘ TRÌNH CHUYÊN MÔN</div><h1>${t[5]} ${t[0]}</h1><p>${t[1]}. Học lý thuyết, thực hành tình huống và kiểm tra kiến thức.</p><p class="metadata">${t[2]} bài học · Cơ bản đến thực hành</p><div class="progress-label"><span>Tiến độ của bạn</span><b>${progress(trackId)}%</b></div>${bar(progress(trackId),t[4])}</div><div class="section-head"><h2>Nội dung lộ trình</h2><span class="metadata">Đạt quiz ≥ 70% để mở khóa phần nâng cao</span></div><div class="timeline">${currentLessons().map((n,i)=>{let locked=i>=4&&(state.scores[trackId]||0)<70,done=state.done.includes(key(trackId,i));return `<button class="lesson-row" ${locked?'disabled':''} data-lesson="${trackId},${i}"><span class="number">${done?'✓':locked?'♙':String(i+1).padStart(2,'0')}</span><div><h3>${n}</h3><p>${i<4?'Cơ bản':'Trung cấp'} · ${8+i*2} phút đọc</p></div><span class="status">${locked?'Khóa':done?'Hoàn thành':i===3?'Đang học':'Bắt đầu'}</span></button>`}).join('')}<button class="primary" id="track-quiz">Làm quiz mở khóa</button></div>`}
function theory(){let title=currentLessons()[lessonId];return `<h2 id="overview">1. Tổng quan</h2><p>${title} giúp Business Analyst hiểu đúng bối cảnh, xác định người liên quan và kết nối nhu cầu kinh doanh với giải pháp phù hợp.</p><p>Stakeholder là cá nhân hoặc nhóm có thể tác động đến, chịu tác động bởi, hoặc có lợi ích liên quan đến một thay đổi. Hiểu góc nhìn của họ là nền tảng để khai thác yêu cầu hiệu quả.</p><div class="callout"><b>ⓘ Lưu ý</b><br>Không chỉ người ra quyết định mới là stakeholder. Hãy cân nhắc cả người sử dụng trực tiếp, bộ phận vận hành, pháp chế và các nhóm chịu ảnh hưởng gián tiếp.</div><h2 id="method">2. Cách phân tích stakeholder</h2><p>Bắt đầu bằng việc liệt kê các bên liên quan. Với mỗi bên, ghi nhận vai trò, mục tiêu, mức độ ảnh hưởng và mức độ quan tâm đến dự án.</p><ul><li><b>Ảnh hưởng cao, quan tâm cao:</b> hợp tác chặt chẽ và thống nhất quyết định.</li><li><b>Ảnh hưởng cao, quan tâm thấp:</b> đảm bảo họ hài lòng với các mốc quan trọng.</li><li><b>Ảnh hưởng thấp, quan tâm cao:</b> cập nhật thông tin và thu thập phản hồi.</li><li><b>Ảnh hưởng thấp, quan tâm thấp:</b> theo dõi và cập nhật khi cần.</li></ul><div class="callout error"><b>! Sai lầm thường gặp</b><br>Đánh giá stakeholder một lần rồi giữ nguyên suốt dự án. Mức độ ảnh hưởng và ưu tiên có thể thay đổi sau mỗi giai đoạn.</div><h2 id="summary">3. Ghi nhớ & áp dụng</h2><p>Lập bản đồ stakeholder là điểm khởi đầu. Giá trị thực sự đến từ việc chọn đúng cách giao tiếp, xác nhận giả định và liên tục cập nhật hiểu biết của bạn.</p><div class="callout tip"><b>✧ Mẹo phỏng vấn</b><br>Khi được hỏi cách xử lý yêu cầu mâu thuẫn, hãy mô tả cách xác định mục tiêu chung, phân tích tác động và thống nhất ưu tiên với người có thẩm quyền.</div>`}
function lessonPage(){return `<div class="lesson-layout"><article class="article"><a href="#" data-track="${trackId}">${tracks[trackId][0]}</a><h1>${currentLessons()[lessonId]}</h1><div class="metadata">Bài ${String(lessonId+1).padStart(2,'0')} · ${8+lessonId*2} phút đọc · Cơ bản</div><div class="tabs">${['Lý thuyết','Ứng dụng thực tế','Ôn tập'].map((n,i)=>`<button data-tab="${i}" style="--tab:${['#5b5bd6','#d58f46','#9b6bd3'][i]}" class="${tab===i?'selected':''}">${n}</button>`).join('')}</div>${tab===0?theory():tab===1?`<h2 id="overview">1. Tình huống thực tế</h2><p>Một công ty bán lẻ muốn xây dựng hệ thống đặt hàng. Bộ phận kinh doanh muốn nhiều khuyến mãi, trong khi vận hành ưu tiên giảm lỗi giao nhận.</p><div class="callout tip"><b>Nhiệm vụ của bạn</b><br>Xác định stakeholder, lập ma trận ảnh hưởng – quan tâm và đề xuất kế hoạch trao đổi cho từng nhóm.</div><h2 id="method">2. Gợi ý tiếp cận</h2><p>Phỏng vấn đại diện kinh doanh, vận hành, kho, tài chính và khách hàng. Làm rõ KPI của từng nhóm trước khi thảo luận tính năng. Tổ chức workshop để thống nhất ưu tiên và ghi nhận các quyết định.</p><h2 id="summary">3. Kết quả mong đợi</h2><p>Một danh sách stakeholder, ma trận phân loại, kế hoạch giao tiếp và biên bản thống nhất mục tiêu. Có thể dùng bảng gồm: tên nhóm, mối quan tâm, ảnh hưởng, kênh liên lạc và tần suất.</p>`:`<h2 id="overview">Tự kiểm tra kiến thức</h2><p>Bạn đã giải thích được stakeholder là ai? Bạn có thể phân loại stakeholder và chọn cách giao tiếp phù hợp chưa?</p><div class="callout">Hoàn thành quiz của track với điểm từ 70% để mở khóa các bài nâng cao.</div><button class="primary" id="track-quiz">Bắt đầu quiz</button><h2 id="method">Gợi ý ôn tập</h2><p>Thử lập bản đồ stakeholder cho một dự án bạn từng tham gia. So sánh cách bạn đã giao tiếp với cách bạn sẽ làm sau bài học này.</p><button class="primary" data-nav="Flashcard">Ôn bằng flashcard</button>`}</article><aside class="toc panel" style="position:sticky;width:auto;height:fit-content;border:0"><h3>Trong bài học này</h3><a href="#overview">Tổng quan & tình huống</a><a href="#method">Phương pháp phân tích</a><a href="#summary">Ghi nhớ & áp dụng</a><p class="metadata">Tiến độ đọc <b id="read-percent">0%</b></p><div id="read-bar">${bar(0)}</div></aside></div><div class="lesson-bottom"><button id="prev-lesson" ${lessonId===0?'disabled':''}>Bài trước</button><button class="primary" id="complete">${state.done.includes(key(trackId,lessonId))?'✓ Đã hoàn thành':'Đánh dấu hoàn thành'}</button><button id="next-lesson" ${lessonId===5?'disabled':''}>Bài sau</button></div>`}
const flashes=[['Stakeholder là gì?','Cá nhân hoặc nhóm có thể ảnh hưởng, chịu ảnh hưởng hoặc có lợi ích liên quan đến một thay đổi.'],['Acceptance Criteria là gì?','Các điều kiện cụ thể mà một giải pháp hoặc user story cần đáp ứng để được chấp nhận.'],['Business Requirement là gì?','Mục tiêu hoặc kết quả cấp cao mà tổ chức mong muốn đạt được từ một thay đổi.'],['MoSCoW dùng để làm gì?','Ưu tiên yêu cầu theo Must have, Should have, Could have và Won’t have trong phạm vi đang xét.']];
function flashPage(){let f=flashes[flashIndex%flashes.length];return heading('Ôn tập bằng flashcard','Một chút nhắc lại, ghi nhớ lâu hơn.')+`<div class="flash-wrap"><p class="metadata" style="text-align:center">THUẬT NGỮ BA · THẺ ${flashIndex%flashes.length+1}/${flashes.length}</p><button class="flashcard" id="flip" aria-label="Lật flashcard"><span class="face">${f[0]}<small>Nhấn để xem đáp án</small></span><span class="face back">${f[1]}<small>Nhấn để quay lại</small></span></button><div class="review-actions"><button id="again">Cần ôn lại</button><button class="primary" id="remember">Đã nhớ</button></div><p class="metadata" style="text-align:center">Đã ôn ${state.review} thẻ · tiến độ lưu trên trình duyệt</p></div>`}
const questions=[['Ai là stakeholder của dự án?',['Chỉ người tài trợ','Chỉ người dùng','Tất cả các bên ảnh hưởng hoặc chịu ảnh hưởng'],2],['Nhóm ảnh hưởng cao, quan tâm cao cần được?',['Hợp tác chặt chẽ','Bỏ qua','Chỉ nhận email khi kết thúc'],0],['Mục tiêu chính của khai thác yêu cầu là?',['Viết càng nhiều tài liệu càng tốt','Hiểu nhu cầu và vấn đề cần giải quyết','Chốt công nghệ trước'],1],['Khi yêu cầu mâu thuẫn, BA nên?',['Tự chọn yêu cầu mình thích','Bỏ qua cả hai','Làm rõ mục tiêu, tác động và thống nhất ưu tiên'],2],['Bản đồ stakeholder nên được cập nhật khi nào?',['Chỉ đầu dự án','Khi vai trò, ưu tiên hoặc bối cảnh thay đổi','Không bao giờ'],1]];
function quizPage(){if(quizIndex>=questions.length){let score=Math.round(answers.filter((a,i)=>a===questions[i][2]).length/questions.length*100);state.scores[quizTrack]=Math.max(state.scores[quizTrack]||0,score);save();return heading('Kết quả ôn tập',tracks[quizTrack][0])+`<section class="panel" style="text-align:center;padding:60px"><div style="font-size:60px;color:var(--primary)">${score}%</div><h2>${score>=70?'Tuyệt vời! Bạn đã mở khóa bài nâng cao.':'Hãy ôn lại và thử thêm lần nữa.'}</h2><p class="metadata">${answers.filter((a,i)=>a===questions[i][2]).length}/5 câu đúng · Điểm mở khóa: 70%</p><button class="primary" id="retry">Làm lại quiz</button> <button data-track="${quizTrack}">Về lộ trình</button></section>`}let q=questions[quizIndex];return heading('Kiểm tra kiến thức',tracks[quizTrack][0])+`<section class="panel" style="max-width:800px;margin:auto;padding:32px"><div class="progress-label"><span>Câu ${quizIndex+1}/5</span><b>Đạt 70% để mở khóa</b></div>${bar(quizIndex/5*100)}<h2 style="font-size:22px;margin-top:30px">${q[0]}</h2>${q[1].map((a,i)=>`<button class="quiz-answer ${answers[quizIndex]!==undefined?(i===q[2]?'correct':i===answers[quizIndex]?'wrong':''):''}" data-answer="${i}" ${answers[quizIndex]!==undefined?'disabled':''}>${String.fromCharCode(65+i)}. ${a}</button>`).join('')}${answers[quizIndex]!==undefined?`<p class="metadata">${answers[quizIndex]===q[2]?'✓ Chính xác!':'Đáp án đúng: '+q[1][q[2]]}</p><button class="primary" id="quiz-next">${quizIndex===4?'Xem kết quả':'Câu tiếp theo'}</button>`:''}</section>`}
const resources={'Phỏng vấn':[['Giới thiệu bản thân theo cấu trúc','Trình bày kinh nghiệm, đóng góp và giá trị bạn mang lại.'],['Xử lý yêu cầu mâu thuẫn','Nêu một ví dụ: bối cảnh, hành động, kết quả và bài học.'],['Câu hỏi tình huống BA','Bạn làm gì khi stakeholder không có thời gian cung cấp yêu cầu?']],'Case study':[['Hệ thống đặt hàng bán lẻ','Xác định stakeholder và mô hình quy trình đặt hàng.'],['Ứng dụng đặt lịch khám','Làm rõ nhu cầu, ngoại lệ và tiêu chí chấp nhận.'],['Quản lý yêu cầu nội bộ','Đề xuất quy trình tiếp nhận, phân loại và phê duyệt.']],'Glossary':flashes.map(([a,b])=>[a.replace(' là gì?',''),b]),'Tin tức':[['Tư duy outcome cho Business Analyst','Phân biệt đầu ra được bàn giao với thay đổi có ý nghĩa cho doanh nghiệp. Đây là nội dung chuyên đề minh họa.'],['AI trong phân tích yêu cầu','Gợi ý cách dùng AI để tổ chức ghi chú, phát hiện điểm chưa rõ và chuẩn bị câu hỏi. Nội dung chuyên đề minh họa.']]};
function resourcePage(){if(page==='Case study')return casePage();if(page==='Thư viện bài học')return libraryPage();if(page==='Glossary')return glossaryPage();return heading(page,'Thư viện nội dung thực hành cho hành trình BA.')+`<div class="resource-grid">${resources[page].map(([n,d],i)=>`<article class="resource"><span class="track-icon" style="--accent:#7771dc">${navs.find(n=>n[0]===page)?.[1]||'◇'}</span><h3>${n}</h3><p>${d}</p><button class="primary" data-resource="${i}">Đọc chi tiết</button></article>`).join('')}</div><section id="resource-detail" style="margin-top:25px"></section>`}
function render(){document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===page||(page==='track'&&b.dataset.nav==='Lộ trình học')||(page==='lesson'&&b.dataset.nav==='Thư viện bài học')));$('#main').innerHTML=page==='Dashboard'?dashboard():page==='Lộ trình học'?heading('Lộ trình học','10 miền kiến thức. Một hành trình phát triển toàn diện.')+trackSection():page==='track'?trackPage():page==='lesson'?lessonPage():page==='Flashcard'?flashPage():page==='Quiz'?quizPage():page==='Thư viện bài học'?libraryPage():page==='Glossary'?glossaryPage():page==='Cài đặt'?heading('Cài đặt','Cá nhân hóa không gian học tập.')+`<section class="panel"><h3>Giao diện</h3><button class="primary" id="settings-theme">Đổi chế độ sáng / tối</button><p class="metadata">Tiến độ và giao diện được lưu trên trình duyệt hiện tại.</p></section>`:resourcePage();document.title=(page==='track'?tracks[trackId][0]:page==='lesson'?currentLessons()[lessonId]:page)+' · Vy Workspace';polish();updateReading();if(page==='Glossary'&&typeof bindGlossaryEvents==='function')bindGlossaryEvents();}
document.addEventListener('click',e=>{let b=e.target.closest('button,a');if(!b)return;if(b.dataset.nav){e.preventDefault();if(b.dataset.nav==='Quiz'){quizIndex=0;answers=[];quizTrack=trackId}go(b.dataset.nav)}if(b.dataset.glOpen){e.preventDefault();go('Glossary');openGlossaryDrawer(b.dataset.glOpen);return}if(b.dataset.track!==undefined){e.preventDefault();openTrack(+b.dataset.track)}if(b.dataset.lesson){let[t,l]=b.dataset.lesson.split(',').map(Number);openLesson(t,l)}if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.dataset.tab){tab=+b.dataset.tab;render()}if(b.id==='theme'||b.id==='settings-theme'){state.dark=!state.dark;save();document.body.classList.toggle('dark',state.dark);$('#theme').innerHTML=uiIcon(state.dark?'sun':'moon')}if(b.id==='notifications')toast('Bạn có 18 flashcard cần ôn. Dành 5 phút để giữ vững kiến thức nhé!');if(b.id==='complete'){let k=key(trackId,lessonId);if(!state.done.includes(k)){state.done.push(k);save();toast('Đã lưu tiến độ. Thêm một bước tiến!')}render()}if(b.id==='prev-lesson'&&lessonId>0)openLesson(trackId,lessonId-1);if(b.id==='next-lesson'){if(lessonId>=3&&(state.scores[trackId]||0)<70)toast('Hoàn thành quiz từ 70% để mở bài tiếp theo.');else if(lessonId<5)openLesson(trackId,lessonId+1)}if(b.id==='track-quiz'){quizTrack=trackId;quizIndex=0;answers=[];go('Quiz')}if(b.id==='flip')b.classList.toggle('flipped');if(b.id==='remember'||b.id==='again'){if(b.id==='remember'){state.review++;save()}flashIndex++;render()}if(b.dataset.answer!==undefined){answers[quizIndex]=+b.dataset.answer;render()}if(b.id==='quiz-next'){quizIndex++;render()}if(b.id==='retry'){quizIndex=0;answers=[];render()}if(b.dataset.resource!==undefined){let i=+b.dataset.resource,[n,d]=resources[page][i];$('#resource-detail').innerHTML=`<article class="panel article"><h2>${esc(n)}</h2><p>${esc(d)}</p><h3>Gợi ý thực hành</h3><p>Chọn một dự án quen thuộc, ghi lại mục tiêu kinh doanh, người liên quan và các giả định cần xác nhận. Đối chiếu kết quả với kiến thức trong lộ trình và bổ sung câu hỏi còn thiếu.</p><button class="primary" data-nav="Lộ trình học">Học kiến thức liên quan</button></article>`;$('#resource-detail').scrollIntoView({behavior:'smooth'})}});
$('#search').addEventListener('input',e=>{let q=e.target.value.trim().toLocaleLowerCase('vi');if(!q){$('#results').innerHTML='';return}let found=[];tracks.forEach((t,i)=>{if((t[0]+' '+t[1]).toLocaleLowerCase('vi').includes(q))found.push(`<button data-track="${i}">Lộ trình · ${t[0]}</button>`)});lessonNames.forEach((n,l)=>{if((n+' '+theory().replace(/<[^>]+>/g,' ')).toLocaleLowerCase('vi').includes(q))found.push(`<button data-lesson="1,${l}">Bài học · ${n}</button>`)});if(typeof glossaryData!=='undefined'){glossaryData.forEach(t=>{if((t.abbr+' '+t.name+' '+t.definition).toLocaleLowerCase('vi').includes(q))found.push(`<button data-gl-open="${t.id}">Thuật ngữ · ${t.abbr}</button>`)});}else{flashes.forEach(([n,d])=>{if((n+d).toLocaleLowerCase('vi').includes(q))found.push(`<button data-nav="Glossary">Thuật ngữ · ${n}</button>`)});}caseStudies.forEach(c=>{if((c.title+' '+c.summary+' '+c.domain+' '+c.skill+' '+c.context).toLocaleLowerCase('vi').includes(q))found.push(`<button data-case-open="${c.id}">Case study · ${c.title}</button>`)});$('#results').innerHTML=found.join('')||'<div class="empty">Không tìm thấy nội dung phù hợp.</div>'});document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))$('#results').innerHTML=''});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus()}if(e.key==='Escape'){$('#results').innerHTML='';$('#search').blur()}});
function updateReading(){if(page!=='lesson')return;let article=$('.article');if(!article)return;let max=Math.max(1,article.offsetHeight-innerHeight+160),v=Math.min(100,Math.max(0,Math.round(scrollY/max*100)));if($('#read-percent'))$('#read-percent').textContent=v+'%';if($('#read-bar'))$('#read-bar').innerHTML=bar(v)}window.addEventListener('scroll',updateReading,{passive:true});render();
